const DATASET = {"part1Data":[{"id":1,"term":"A computer","clue":"electronic machine ... process the data","def":"is an electronic machine which can accept data in a certain form, process the data, and give the results of the processing in a specified format as information.","vn":"Máy tính là máy điện tử nhận dữ liệu, xử lý và xuất ra thông tin.","tip":"electronic machine + process data"},{"id":2,"term":"A clock","clue":"timing of signals","def":"controls the timing of signals in the computer.","vn":"Đồng hồ điều khiển nhịp xung/thời gian của các tín hiệu trong máy tính.","tip":"clock = timing of signals"},{"id":3,"term":"A cloud database","clue":"virtualized environment","def":"is an automated or built-in database for such a virtualized environment.","vn":"Cơ sở dữ liệu đám mây hoạt động trên môi trường ảo hóa.","tip":"cloud = virtualized"},{"id":4,"term":"A gateway","clue":"entrance to another network","def":"is an entrance to another network.","vn":"Cổng gateway là lối vào để kết nối sang một mạng khác.","tip":"gate = entrance"},{"id":5,"term":"A hub","clue":"channels incoming data","def":"channels incoming data maintains the bandwidth speed.","vn":"Hub điều phối và chuyển kênh dữ liệu đến.","tip":"hub = channels incoming data"},{"id":6,"term":"A modem","clue":"modulates and demodulates","def":"modulates and demodulates the data into a digital or an analog signal.","vn":"Modem: viết tắt của Modulator - Demodulator (điều chế tín hiệu số/tương tự).","tip":"Mo-dem = Modulates + Demodulates"},{"id":7,"term":"A network topology","clue":"layout of the interconnections","def":"is the layout of the interconnections of the nodes of a computer network which depends on the distance involved, the type of hardware used and the stability needed.","vn":"Topology là sơ đồ bố cục các kết nối giữa các nút mạng.","tip":"topology = layout of interconnections"},{"id":8,"term":"Algorithm","clue":"set of instructions for solving a specific problem","def":"a predetermined set of instructions for solving a specific problem in a limited number of steps.","vn":"Thuật toán là tập hợp hữu hạn các chỉ dẫn để giải quyết một bài toán cụ thể.","tip":"algorithm = instructions for solving problem"},{"id":9,"term":"Animations","clue":"moving pictures","def":"are made up of a series of independent pictures put together in sequence to look like moving pictures.","vn":"Hoạt họa là chuỗi ảnh độc lập ghép lại tạo cảm giác chuyển động.","tip":"animations = moving pictures"},{"id":10,"term":"Artificial","clue":"made by humans, not natural","def":"made by humans, not natural.","vn":"Nhân tạo nghĩa là do con người làm ra, không phải tự nhiên.","tip":"artificial = made by humans"},{"id":11,"term":"Artificial intelligence","clue":"human intelligence","def":"is a broad area of computer science that makes machines seem like they have human intelligence.","vn":"Trí tuệ nhân tạo (AI) giúp máy móc có trí thông minh như con người.","tip":"AI = human intelligence"},{"id":12,"term":"Background","clue":"colors and patterns of a web page","def":"the underlying colors and patterns of a web page.","vn":"Background là màu sắc nền và họa tiết chìm của trang web.","tip":"background = colors and patterns"},{"id":13,"term":"Blogging","clue":"online journal","def":"is a type of online journal in which the user can update daily, share, follow and post comments.","vn":"Blogging là hình thức viết nhật ký trực tuyến cập nhật thường xuyên.","tip":"blog = online journal"},{"id":14,"term":"Bot","clue":"works automatically","def":"a computer program that works automatically, especially one that searches for and finds information on the Internet.","vn":"Bot là chương trình chạy tự động tìm kiếm thông tin trên mạng.","tip":"bot = works automatically"},{"id":15,"term":"Browser hijacker","clue":"changes a browser’s behavior","def":"is malicious software that changes a browser’s behavior, settings, or appearance without user consent.","vn":"Phần mềm cướp trình duyệt thay đổi giao diện, thiết lập trái phép.","tip":"browser hijacker = changes browser's behavior"},{"id":16,"term":"Cache","clue":"provides fast access","def":"provides fast access for sections of a program and its data.","vn":"Cache là bộ nhớ đệm giúp truy xuất dữ liệu cực nhanh.","tip":"cache = fast access"},{"id":17,"term":"Cascading Style Sheets (CSS)","clue":"adding styles","def":"a mechanism for adding styles to web documents.","vn":"CSS là cơ chế thêm phong cách/định dạng (styles) cho tài liệu web.","tip":"CSS = adding styles"},{"id":18,"term":"Central processing unit (CPU)","clue":"brain of the computer","def":"is considered the brain of the computer.","vn":"CPU được coi là bộ não xử lý trung tâm của máy tính.","tip":"CPU = brain of computer"},{"id":19,"term":"Centralized Database","clue":"stored centrally","def":"The data is stored centrally and users from different locations can access this data.","vn":"CSDL tập trung: dữ liệu được lưu tại một nơi trung tâm duy nhất.","tip":"centralized = stored centrally"},{"id":20,"term":"DBMS","clue":"software used in databases","def":"the software used in databases to store, organized and retrieve the data.","vn":"DBMS (Hệ quản trị CSDL) là phần mềm dùng để lưu trữ và truy xuất dữ liệu.","tip":"DBMS = software used in databases"},{"id":21,"term":"End User Database","clue":"for the end-user","def":"a collaborative database that is designed specifically for the end-user as do the managers at various levels.","vn":"CSDL thiết kế riêng cho đối tượng người dùng cuối.","tip":"end user database = for the end-user"},{"id":22,"term":"Frames","clue":"rectangular areas","def":"rectangular areas that allow the display of different pages in the same browser window.","vn":"Frames là các vùng hình chữ nhật hiển thị các trang con trong cùng cửa sổ.","tip":"frames = rectangular areas"},{"id":23,"term":"Hard drive","clue":"magnetic device","def":"magnetic device used to store information.","vn":"Ổ cứng HDD là thiết bị lưu trữ bằng từ tính.","tip":"hard drive = magnetic device"},{"id":24,"term":"Hardware","clue":"see or touch","def":"is an electronic or mechanic part you can see or touch.","vn":"Phần cứng là các linh kiện có thể nhìn thấy hoặc sờ chạm được.","tip":"hardware = see or touch"},{"id":25,"term":"Hyperlinks","clue":"links to other pages","def":"are highlighted texts or pictures (buttons, image maps, etc.) that act as links to other pages.","vn":"Siêu liên kết dẫn tới các trang web khác.","tip":"hyperlinks = links to other pages"},{"id":26,"term":"Input devices","clue":"data to go into memory","def":"enable data to go into the computer’s memory.","vn":"Thiết bị nhập cho phép dữ liệu đi VÀO bộ nhớ máy tính.","tip":"input = go into"},{"id":27,"term":"Instant message","clue":"short message for free","def":"is a kind of service that allows people to send short message for free.","vn":"Nhắn tin tức thời là dịch vụ gửi tin nhắn ngắn miễn phí.","tip":"instant message = short message"},{"id":28,"term":"Java applets","clue":"small programs","def":"small programs that enable the creation of interactive files.","vn":"Java applets là các chương trình con nhỏ nhúng trên trình duyệt.","tip":"applet = small programs"},{"id":29,"term":"Monitor","clue":"on a screen","def":"displays the output from a computer on a screen.","vn":"Màn hình hiển thị kết quả xuất ra máy tính.","tip":"monitor = screen"},{"id":30,"term":"Nanotechnology","clue":"single atoms and molecules","def":"the science of making devices from single atoms and molecules.","vn":"Công nghệ nano chế tạo thiết bị từ cấp độ nguyên tử và phân tử.","tip":"nano = atoms and molecules"},{"id":31,"term":"Operating system","clue":"between applications and hardware","def":"is the set of programs between the applications programs and the hardware.","vn":"Hệ điều hành đứng ở giữa làm cầu nối giữa phần cứng và phần mềm ứng dụng.","tip":"OS = between applications and hardware"},{"id":32,"term":"Password","clue":"secret word","def":"A secret word that you type into a computer before you use it.","vn":"Mật khẩu là từ bí mật nhập vào trước khi sử dụng.","tip":"password = secret word"},{"id":33,"term":"Peripherals","clue":"physical units attached","def":"are the physical units attached to the computer.","vn":"Thiết bị ngoại vi là các bộ phận vật lý gắn ngoài máy tính.","tip":"peripherals = attached to computer"},{"id":34,"term":"Podcasting","clue":"audio only broadcast","def":"is a free service in which audio only broadcast released on the internet and users can download to listen.","vn":"Podcast là chương trình phát sóng chỉ có âm thanh (nghe).","tip":"podcast = audio only"},{"id":35,"term":"Ports","clue":"sockets","def":"sockets into which an external device may be connected.","vn":"Cổng kết nối là các ổ cắm để cắm thiết bị ngoại vi vào.","tip":"ports = sockets"},{"id":36,"term":"Processor","clue":"controls all the operations","def":"controls all the operations in a computer.","vn":"Bộ xử lý điều khiển toàn bộ các hoạt động tính toán trong máy tính.","tip":"processor = controls all operations"},{"id":37,"term":"RAM","clue":"read or written","def":"holds data read or written to it by the processor.","vn":"RAM là bộ nhớ cho phép bộ xử lý đọc và ghi dữ liệu.","tip":"RAM = read or written"},{"id":38,"term":"Ransomware","clue":"hold information at ransom","def":"is malware that employs encryption to hold a victim’s information at ransom. A user or organization’s critical data is encrypted so that they cannot access files, databases, or application.","vn":"Mã độc tống tiền mã hóa dữ liệu đòi tiền chuộc.","tip":"ransomware = at ransom"},{"id":39,"term":"ROM","clue":"start up the computer","def":"hold instructions which are needed to start up the computer.","vn":"ROM chứa các chỉ dẫn cần thiết để khởi động máy tính.","tip":"ROM = start up computer"},{"id":40,"term":"Software","clue":"set of instructions / program","def":"is a set of instructions, called a program, which tells the computer what to do.","vn":"Phần mềm là tập hợp các câu lệnh (chương trình) bảo máy tính phải làm gì.","tip":"software = program / instructions"},{"id":41,"term":"Spyware","clue":"covertly / computer activities","def":"software that enables a user to obtain convert information about another’s computer activities by transmitting data covertly from their hard drive.","vn":"Phần mềm gián điệp bí mật (covertly) theo dõi và gửi dữ liệu về kẻ tấn công.","tip":"spy = covertly"},{"id":42,"term":"Tags","clue":"placed around pieces of text","def":"are placed around pieces of text to tell the web browser how to display text or pictures.","vn":"Các thẻ (tag HTML) đặt bao quanh đoạn văn bản để chỉ định hiển thị.","tip":"tags = placed around text"},{"id":43,"term":"Teleworking","clue":"working at home","def":"the practice of working at home and communicating with the office by phone and computer.","vn":"Làm việc từ xa/tại nhà qua điện thoại và máy tính.","tip":"teleworking = working at home"},{"id":44,"Trojan":"Trojan","term":"Trojan","clue":"take control of your computer","def":"is a type of malicious code or software that can take control of your computer.","vn":"Trojan là mã độc ngụy trang để chiếm quyền kiểm soát máy tính.","tip":"Trojan = take control"},{"id":45,"term":"Video casting","clue":"videos created and uploaded to Youtube","def":"This is a type of communication in which videos are created and uploaded to a website like Youtube.","vn":"Phát video: sáng tạo nội dung video và tải lên các nền tảng như YouTube.","tip":"videocasting = videos uploaded to Youtube"},{"id":46,"term":"Video conferencing","clue":"video call to one or more people","def":"refers to a set of technologies that allow a person to make a video call to one or more people at the same time.","vn":"Hội nghị truyền hình cho phép gọi video nhiều người cùng lúc.","tip":"video conferencing = video call multiple people"},{"id":47,"term":"Visitor map","clue":"where the visitors to your site are from","def":"information about where the visitors to your site are from.","vn":"Bản đồ khách truy cập hiển thị thông tin vị trí người xem trang web.","tip":"visitor map = where visitors are from"},{"id":48,"term":"VOIP","clue":"telephone calls over the internet","def":"is a service to make telephone calls over the internet rather than through the traditional telephone or cell phone networks.","vn":"VOIP là dịch vụ truyền giọng nói/gọi thoại qua giao thức mạng Internet.","tip":"VOIP = telephone calls over internet"},{"id":49,"term":"Systems Analyst","clue":"studies computer systems, designs solutions","def":"A person who studies an organization's current computer systems and procedures and designs information system solutions to help the organization operate more efficiently.","vn":"Chuyên viên phân tích hệ thống nghiên cứu quy trình và thiết kế giải pháp hệ thống thông tin.","tip":"systems analyst = studies systems & designs solutions"},{"id":50,"term":"Database Administrator (DBA)","clue":"maintaining, securing, optimal performance of databases","def":"An IT professional responsible for directing, maintaining, securing, and ensuring the optimal performance and backup of databases.","vn":"Quản trị viên cơ sở dữ liệu (DBA) chịu trách nhiệm duy trì, bảo mật và tối ưu hiệu năng CSDL.","tip":"DBA = maintaining & securing databases"},{"id":51,"term":"Motherboard","clue":"main printed circuit board, connects CPU, memory","def":"The main printed circuit board in a computer that holds and connects the CPU, memory, expansion slots, and peripheral interfaces.","vn":"Bo mạch chủ là bảng mạch in chính kết nối CPU, RAM và các linh kiện.","tip":"motherboard = main printed circuit board"},{"id":52,"term":"Arithmetic Logic Unit (ALU)","clue":"arithmetic operations, logical evaluations","def":"The electronic circuit inside the CPU that executes basic arithmetic operations (addition, subtraction) and logical evaluations (AND, OR, NOT).","vn":"Khối số học logic (ALU) thực hiện các phép toán số học và so sánh logic trong CPU.","tip":"ALU = arithmetic operations & logical evaluations"},{"id":53,"term":"Control Unit (CU)","clue":"directs operation, coordinates flow of data","def":"The CPU component that directs the operation of the processor and coordinates the flow of data and instructions.","vn":"Khối điều khiển (CU) điều phối hoạt động của bộ xử lý và luồng dữ liệu/chỉ lệnh.","tip":"control unit = directs operation & coordinates flow"},{"id":54,"term":"Solid State Drive (SSD)","clue":"flash memory, no moving mechanical parts","def":"A high-speed storage device that uses integrated circuit assemblies (flash memory) to store data persistently without moving mechanical parts.","vn":"Ổ cứng thể rắn (SSD) dùng chip nhớ flash, tốc độ cao và không có bộ phận cơ học chuyển động.","tip":"SSD = flash memory, no moving mechanical parts"},{"id":55,"term":"Primary Key","clue":"uniquely identifies each record","def":"A unique attribute or set of attributes in a relational database table that uniquely identifies each individual record.","vn":"Khóa chính là thuộc tính định danh duy nhất cho từng bản ghi trong bảng CSDL.","tip":"primary key = uniquely identifies each record"},{"id":56,"term":"Foreign Key","clue":"matches primary key of another table, relationship","def":"A field in one database table that refers to and matches the primary key of another table, establishing a relationship between the two tables.","vn":"Khóa ngoại liên kết tới khóa chính của bảng khác để tạo mối quan hệ giữa hai bảng.","tip":"foreign key = matches primary key of another table"},{"id":57,"term":"Data Redundancy","clue":"unnecessary duplication of identical data","def":"The unnecessary duplication of identical data across multiple records or tables in a database, which wastes storage and can lead to inconsistency.","vn":"Dư thừa dữ liệu là sự trùng lặp dữ liệu không cần thiết, gây tốn dung lượng và không nhất quán.","tip":"data redundancy = duplication of identical data"},{"id":58,"term":"Database Normalization","clue":"structuring database, minimize redundancy, anomalies","def":"The process of structuring a relational database to minimize data redundancy and prevent undesirable update, insert, or delete anomalies.","vn":"Chuẩn hóa CSDL là quá trình tổ chức bảng nhằm giảm dư thừa và tránh dị thường thêm/xóa/sửa.","tip":"normalization = minimize redundancy & anomalies"},{"id":59,"term":"Machine Learning","clue":"learn autonomously from data, without explicit programming","def":"A subfield of artificial intelligence that gives computers the ability to learn and improve autonomously from data without being explicitly programmed.","vn":"Học máy cho phép máy tính tự học và cải thiện từ dữ liệu mà không cần lập trình chi tiết từng bước.","tip":"machine learning = learn autonomously from data"},{"id":60,"term":"Natural Language Processing (NLP)","clue":"understand, interpret human language","def":"A branch of artificial intelligence that focuses on enabling computers to understand, interpret, and generate human language in spoken and written forms.","vn":"Xử lý ngôn ngữ tự nhiên (NLP) giúp máy tính hiểu và tạo ngôn ngữ con người (nói và viết).","tip":"NLP = understand & interpret human language"},{"id":61,"term":"Star Topology","clue":"connected directly to a central hub/switch","def":"A network topology where every peripheral node is connected directly to a central hub, switch, or computer.","vn":"Mạng hình sao kết nối tất cả các máy trạm trực tiếp vào thiết bị trung tâm (switch/hub).","tip":"star topology = connected to central hub/switch"},{"id":62,"term":"Network Switch","clue":"intelligent, uses MAC addresses, only to destination","def":"An intelligent network hardware device that connects devices on a local area network (LAN) and uses MAC addresses to forward data only to the specific destination device.","vn":"Bộ chuyển mạch (Switch) dùng địa chỉ MAC chuyển tiếp dữ liệu chính xác đến cổng đích.","tip":"switch = MAC addresses, only to destination"},{"id":63,"term":"Broadband","clue":"high-capacity, wide band of frequencies","def":"A high-capacity telecommunications transmission technique using a wide band of frequencies to transmit multiple data streams simultaneously.","vn":"Băng thông rộng là kỹ thuật truyền dẫn dung lượng cao dùng dải tần rộng truyền nhiều luồng dữ liệu cùng lúc.","tip":"broadband = wide band of frequencies"},{"id":64,"term":"Uniform Resource Locator (URL)","clue":"unique address, locate resource on WWW","def":"The unique address used to locate and access a specific resource, file, or page on the World Wide Web.","vn":"Định vị tài nguyên thống nhất (URL) là địa chỉ duy nhất dùng định vị tệp/trang trên web.","tip":"URL = unique address to locate resource"},{"id":65,"term":"Firewall","clue":"monitors and filters traffic, predetermined security rules","def":"A network security device or software that monitors and filters incoming and outgoing network traffic based on predetermined security rules.","vn":"Tường lửa là thiết bị hoặc phần mềm giám sát và lọc lưu lượng mạng theo quy tắc bảo mật xác định.","tip":"firewall = filters network traffic by rules"},{"id":66,"term":"Internet of Things (IoT)","clue":"physical objects, sensors, exchange data","def":"A network of physical objects embedded with sensors, software, and network connectivity that enables them to collect and exchange data.","vn":"Internet vạn vật (IoT) kết nối các thiết bị vật lý có cảm biến để thu thập và trao đổi dữ liệu qua mạng.","tip":"IoT = physical objects with sensors exchanging data"},{"id":67,"term":"Quantum Computing","clue":"superposition, qubits, exponentially faster","def":"A technology using quantum mechanical phenomena (such as superposition and qubits) to perform complex calculations exponentially faster than classical computers.","vn":"Điện toán lượng tử dùng hiện tượng cơ học lượng tử (qubit, superposition) xử lý phép tính siêu nhanh.","tip":"quantum computing = qubits & superposition"},{"id":68,"term":"Software as a Service (SaaS)","clue":"hosts applications, end-users over internet on demand","def":"A cloud computing distribution model where a third-party provider hosts applications and makes them available to end-users over the internet on demand.","vn":"Phần mềm dạng dịch vụ (SaaS) cung cấp ứng dụng trên đám mây cho người dùng qua trình duyệt web.","tip":"SaaS = hosts applications over internet on demand"}],"part2Data":[{"id":1,"sentence":"__________ are designed to be worn on the body or integrated into the user’s clothing.","answer":"Wearables","clue":"worn on the body","options":["Wearables","Laptops","Tablets","Mainframes"],"vn":"Thiết bị đeo (Wearables) được thiết kế để đeo trên cơ thể hoặc tích hợp vào quần áo."},{"id":2,"sentence":"__________ is software that displays unwanted advertisements on your computer.","answer":"Adware","clue":"advertisements","options":["Adware","Spyware","Shareware","Freeware"],"vn":"Adware là phần mềm hiển thị quảng cáo không mong muốn."},{"id":3,"sentence":"__________ is a type of malware that prevents you from using your computer or accessing specific files on your computer unless a ransom is paid.","answer":"Ransomware","clue":"ransom is paid","options":["Ransomware","Worm","Virus","Phishing"],"vn":"Ransomware là mã độc tống tiền khóa dữ liệu."},{"id":4,"sentence":"An operating system has three main functions: manage the computer's resources, such as the central processing unit, __________, disk drives, and printers, establish a user interface, and execute and provide services for applications software.","answer":"memory","clue":"CPU, [?], disk drives","options":["memory","keyboard","mouse","monitor"],"vn":"Hệ điều hành quản lý tài nguyên: CPU, bộ nhớ (memory), ổ đĩa..."},{"id":5,"sentence":"Electronic communication is fast, __________ and convenient, but these attributes contain inherent disadvantages.","answer":"cheap","clue":"fast, [?], convenient","options":["cheap","expensive","slow","hard"],"vn":"Truyền thông điện tử thì nhanh, rẻ (cheap) và thuận tiện."},{"id":6,"sentence":"__________ enable us to extract the finish product from the system.","answer":"Output devices","clue":"extract product","options":["Output devices","Input devices","Storage devices","Cables"],"vn":"Thiết bị xuất (Output devices) giúp ta lấy kết quả hoàn chỉnh ra ngoài."},{"id":7,"sentence":"__________ is a type of malware that prevents you from using your computer or accessing specific files on your computer unless a ransom is paid.","answer":"Ransomware","clue":"ransom is paid","options":["Ransomware","Trojan","Spyware","Adware"],"vn":"Ransomware là mã độc tống tiền."},{"id":8,"sentence":"__________ means copying data to another place so that you don’t lose it.","answer":"Backing up","clue":"copying data... not lose it","options":["Backing up","Deleting","Formatting","Encrypting"],"vn":"Sao lưu (Backing up) là chép dữ liệu sang nơi khác để không bị mất."},{"id":9,"sentence":"__________ is a set of instructions, called a program, which tells the computer what to do.","answer":"Software","clue":"set of instructions, program","options":["Software","Hardware","Firmware","Malware"],"vn":"Phần mềm (Software) là tập hợp các chỉ dẫn điều khiển máy tính."},{"id":10,"sentence":"A __________ can manage any type of data, including text, numbers, images, sound and video and hyperlinks.","answer":"multimedia database","clue":"sound and video","options":["multimedia database","relational database","flat file","text file"],"vn":"CSDL đa phương tiện (multimedia database) quản lý cả âm thanh, hình ảnh, video."},{"id":11,"sentence":"A __________ connects computers over a relatively short distance, allowing them to share data, files, and resources.","answer":"LAN","clue":"short distance","options":["LAN","WAN","MAN","SAN"],"vn":"Mạng cục bộ (LAN) kết nối khoảng cách ngắn trong phòng/tòa nhà."},{"id":12,"sentence":"A __________ database in which various parts of a database are located in different physical locations along with databases replicated and distributed between different points in a network can be imagined.","answer":"distributed","clue":"different physical locations","options":["distributed","centralized","personal","local"],"vn":"CSDL phân tán (distributed database) đặt ở nhiều vị trí địa lý khác nhau."},{"id":13,"sentence":"A network topology is the layout of the interconnections of the __________ of a computer network.","answer":"nodes","clue":"interconnections of the...","options":["nodes","users","wires","emails"],"vn":"Sơ đồ mạng là bố cục liên kết giữa các nút (nodes) mạng."},{"id":14,"sentence":"A record about an employee might consist of several __________ which give their name, address, phone number, date of birth, salary and length of employment.","answer":"fields","clue":"name, address...","options":["fields","files","folders","bytes"],"vn":"Một bản ghi gồm nhiều trường (fields) như tên, địa chỉ, ngày sinh..."},{"id":15,"sentence":"Artificial Intelligence is slowly making progress, but it could soon __________ into a new trend in technology.","answer":"evolve","clue":"into a new trend","options":["evolve","stop","die","break"],"vn":"AI đang dần tiến bộ và có thể sớm phát triển (evolve) thành xu hướng mới."},{"id":16,"sentence":"But in the modern world, telecommunications mainly means transferring information across the Internet, via modem, phone lines or __________ networks.","answer":"wireless","clue":"modem, phone lines or...","options":["wireless","paper","manual","offline"],"vn":"Mạng không dây (wireless networks)."},{"id":17,"sentence":"By using __________, one can send a message to another person through a mail immediately.","answer":"email","clue":"mail immediately","options":["email","fax","post office","letter"],"vn":"Dùng thư điện tử (email) để gửi tin nhắn ngay lập tức."},{"id":18,"sentence":"Don’t use common words or numbers as __________, such as birthdays or names of your children.","answer":"passwords","clue":"birthdays or names","options":["passwords","usernames","addresses","domains"],"vn":"Không dùng ngày sinh làm mật khẩu (passwords)."},{"id":19,"sentence":"Due to the advancement of electronic media, business managers can effortlessly manage __________ transversely the world.","answer":"businesses","clue":"manage [?] transversely the world","options":["businesses","weather","mountains","rivers"],"vn":"Quản lý công việc kinh doanh (businesses) trên toàn thế giới."},{"id":20,"sentence":"Electronic communication can be classified into different types like messaging, voice call, e-mail, __________, etc.","answer":"video conferencing","clue":"messaging, voice call...","options":["video conferencing","sleeping","cooking","running"],"vn":"Hội nghị truyền hình (video conferencing)."},{"id":21,"sentence":"Hackers try to trick email recipients into believing that a message is genuine... so that they click on a link or open an __________.","answer":"attachment","clue":"click on a link or open an...","options":["attachment","envelope","application","account"],"vn":"Mở tệp đính kèm (attachment) độc hại."},{"id":22,"sentence":"Heterogeneous and homogenous are the two kinds of distribution __________.","answer":"database","clue":"Heterogeneous and homogenous","options":["database","monitor","cable","printer"],"vn":"Hệ CSDL phân tán thuần nhất và hỗn hợp (distribution database)."},{"id":23,"sentence":"HTML is a language that is all about the __________ of your information, not what the actual data is.","answer":"formatting","clue":"not what actual data is","options":["formatting","security","price","speed"],"vn":"HTML quy định định dạng/trình bày (formatting/structure) hiển thị."},{"id":24,"sentence":"If you want to inject something special into your web pages, you can use Adobe Flash to include interactive __________ and streaming audio.","answer":"animations","clue":"Adobe Flash","options":["animations","hardware","cables","routers"],"vn":"Adobe Flash chèn các hoạt ảnh (animations) tương tác."},{"id":25,"sentence":"If you want to share __________ with people, you can use RSS feeds and provide readers with a link to the feed.","answer":"news","clue":"RSS feeds","options":["news","money","hardware","passwords"],"vn":"Chia sẻ tin tức (news/content) bằng RSS feeds."},{"id":26,"sentence":"In __________, all nodes are connected to a common medium, call backbone, as it happens with Christmas lights.","answer":"bus topology","clue":"common medium, backbone","options":["bus topology","star topology","ring topology","mesh topology"],"vn":"Mạng hình trục (bus topology): các nút nối vào một đường trục chính backbone."},{"id":27,"sentence":"In a __________ network all nodes are connected to a common medium, call backbone, as it happens with Christmas lights.","answer":"bus","clue":"common medium, backbone","options":["bus","star","ring","tree"],"vn":"Mạng Bus."},{"id":28,"sentence":"In basic terms, AI is a __________ area of computer science that makes machines seem like they have human intelligence.","answer":"broad","clue":"area of computer science","options":["broad","narrow","tiny","bad"],"vn":"AI là một lĩnh vực rộng lớn (broad area) của khoa học máy tính."},{"id":29,"sentence":"In recent years, TV and radio broadcasting has been revolutionized by developments in satellite and __________ transmission.","answer":"digital","clue":"satellite and [?] transmission","options":["digital","manual","hand","paper"],"vn":"Truyền dẫn số (digital transmission) và vệ tinh."},{"id":30,"sentence":"In the ideal smart home, appliances and electronic devices work in __________ to keep the house secure.","answer":"harmony","clue":"work in [?]","options":["harmony","conflict","danger","trouble"],"vn":"Các thiết bị hoạt động hòa hợp/đồng bộ (harmony) với nhau."},{"id":31,"sentence":"In the near future we may have __________ pets, with video camera eyes and microphone ears, linked by radio to the family computer.","answer":"robotic","clue":"video camera eyes","options":["robotic","real","dead","wild"],"vn":"Thú cưng robot (robotic pets)."},{"id":32,"sentence":"Instant messaging is a service, like SMS, that __________ people to send short messages using their mobiles phones.","answer":"enables","clue":"people to send","options":["enables","prevents","stops","punishes"],"vn":"Cho phép (enables/allows) mọi người gửi tin nhắn ngắn."},{"id":33,"sentence":"Like human, a __________ retains information and becomes smarter over time.","answer":"neural network","clue":"retains information, smarter","options":["neural network","stone","cable","battery"],"vn":"Mạng nơ-ron (neural network/machine) ghi nhớ thông tin và thông minh hơn theo thời gian."},{"id":34,"sentence":"Netflix and Google announced reducing video streaming quality to prevent network __________ and collapse.","answer":"congestion","clue":"and collapse","options":["congestion","freedom","speed","success"],"vn":"Ngăn chặn nghẽn mạng (network congestion) và sụp đổ đường truyền."},{"id":35,"sentence":"Neural networks help solve the problem of providing higher revenue at __________ costs.","answer":"lower","clue":"higher revenue at [?] costs","options":["lower","higher","infinite","extreme"],"vn":"Đem lại doanh thu cao hơn với chi phí thấp hơn (lower costs)."},{"id":36,"sentence":"Neural networks, also called __________ neural networks, are ways of achieving deep learning.","answer":"artificial","clue":"neural networks","options":["artificial","natural","biological","human"],"vn":"Mạng nơ-ron nhân tạo (artificial neural networks - ANN)."},{"id":37,"sentence":"No __________ user can access the information.","answer":"unauthorized","clue":"can access the information","options":["unauthorized","registered","admin","good"],"vn":"Không người dùng trái phép nào (unauthorized user) có thể truy cập."},{"id":38,"sentence":"Nowadays, data are stored in public, hybrid or private cloud, also known as a __________ environment.","answer":"virtualized","clue":"cloud","options":["virtualized","physical","wooden","paper"],"vn":"Môi trường ảo hóa (virtualized environment)."},{"id":39,"sentence":"On the other hand, __________ may be difficult to set up and may be insecure as computer hackers can send viruses...","answer":"networks","clue":"send viruses to the net computer","options":["networks","keyboards","monitors","mouse"],"vn":"Mạng máy tính (networks) có thể khó thiết lập và tiềm ẩn nguy cơ an ninh."},{"id":40,"sentence":"Thanks to advances in processing speeds, __________ can actually make sense of all this information more quickly.","answer":"computers","clue":"make sense of information","options":["computers","books","pens","cables"],"vn":"Máy tính (computers) xử lý thông tin nhanh hơn."},{"id":41,"sentence":"Thanks to books and movies, each generation has formed its own fantasy of a world ruled or at least served by __________.","answer":"robots","clue":"ruled or served by","options":["robots","animals","aliens","plants"],"vn":"Thế giới được phục vụ bởi robot."},{"id":42,"sentence":"The __________ of large-size, unstructured information can be done very efficiently on several cloud virtual servers.","answer":"analysis","clue":"large-size, unstructured information","options":["analysis","deletion","destruction","loss"],"vn":"Phân tích (analysis) dữ liệu phi cấu trúc kích thước lớn."},{"id":43,"sentence":"The __________ of information in a network is controlled by communications protocols...","answer":"transmission","clue":"of information in a network","options":["transmission","destruction","stop","ending"],"vn":"Sự truyền tải thông tin (transmission of information) được kiểm soát bởi giao thức."},{"id":44,"sentence":"The best database packages also include network facilities, which can make business more __________.","answer":"productive","clue":"make business more","options":["productive","slow","lazy","broken"],"vn":"Làm cho doanh nghiệp năng suất/hiệu quả hơn (productive)."},{"id":45,"sentence":"The role of the operating system is to __________ directly with the hardware.","answer":"communicate","clue":"directly with hardware","options":["communicate","fight","hide","break"],"vn":"Giao tiếp/tương tác trực tiếp (communicate) với phần cứng."},{"id":46,"sentence":"There are three basic hardware sections: the CPU, main memory and __________.","answer":"peripherals","clue":"CPU, memory and...","options":["peripherals","software","internet","cloud"],"vn":"3 phần cơ bản: CPU, bộ nhớ chính và thiết bị ngoại vi (peripherals)."},{"id":47,"sentence":"There is no central hub, and communication is sent in one direction around the __________ through the use of a token.","answer":"ring","clue":"around the [?] ... token","options":["ring","star","bus","tree"],"vn":"Mạng Token Ring: truyền dữ liệu một chiều quanh vòng (ring)."},{"id":48,"sentence":"When you ask Siri or Cortana... it’s feeding it to a __________.","answer":"search engine","clue":"feeding it to a [?]","options":["search engine","printer","speaker","scanner"],"vn":"Đưa dữ liệu vào công cụ tìm kiếm (search engine)."},{"id":49,"sentence":"While people are mostly using home WiFi, they would still use their mobile phones for voice __________.","answer":"calls","clue":"voice [?]","options":["calls","screens","cases","batteries"],"vn":"Cuộc gọi thoại (voice calls)."},{"id":50,"sentence":"With potential congestion of fixed broadband, devices will fall back on __________ networks.","answer":"cellular","clue":"mobile data traffic","options":["cellular","wired","satellite","fiber"],"vn":"Mạng di động tế bào (cellular networks)."},{"id":51,"sentence":"A __________ is responsible for writing, testing, and debugging the source code of applications and system programs.","answer":"software developer","clue":"writing, testing, debugging source code","options":["software developer","web designer","data entry clerk","cable installer"],"vn":"Lập trình viên (software developer) viết mã, kiểm thử và gỡ lỗi phần mềm."},{"id":52,"sentence":"The central processing unit (CPU) consists of two main functional components: the control unit and the __________.","answer":"arithmetic logic unit","clue":"control unit and [?]","options":["arithmetic logic unit","hard drive","network adapter","optical disc"],"vn":"CPU gồm hai khối cốt lõi: Khối điều khiển (CU) và Khối số học logic (ALU)."},{"id":53,"sentence":"Unlike traditional hard disk drives that use magnetic platters, __________ rely on flash memory, providing much faster data access speeds.","answer":"solid-state drives","clue":"flash memory, much faster","options":["solid-state drives","floppy disks","CD-ROMs","tape streamers"],"vn":"Ổ cứng thể rắn (solid-state drives - SSDs) dùng bộ nhớ flash, tốc độ vượt trội so với HDD."},{"id":54,"sentence":"In a relational database table, a __________ uniquely identifies each record and ensures that no duplicate rows exist.","answer":"primary key","clue":"uniquely identifies each record","options":["primary key","foreign key","query clause","database schema"],"vn":"Khóa chính (primary key) định danh duy nhất cho từng bản ghi trong bảng."},{"id":55,"sentence":"Database __________ is the systematic technique used to organize data into tables to eliminate redundancy and prevent data anomalies.","answer":"normalization","clue":"eliminate redundancy, anomalies","options":["normalization","corruption","encryption","fragmentation"],"vn":"Chuẩn hóa CSDL (normalization) giúp loại bỏ trùng lặp và dị thường dữ liệu."},{"id":56,"sentence":"To retrieve specific information from a database table based on certain conditions, programmers use the SQL __________ command.","answer":"SELECT","clue":"retrieve specific information","options":["SELECT","INSERT","DROP","CREATE"],"vn":"Câu lệnh SELECT dùng để trích xuất dữ liệu từ bảng CSDL theo điều kiện."},{"id":57,"sentence":"__________ is an advanced branch of machine learning that utilizes multi-layered artificial neural networks to analyze complex data patterns.","answer":"Deep learning","clue":"multi-layered artificial neural networks","options":["Deep learning","Data entry","Cloud hosting","Network routing"],"vn":"Học sâu (Deep learning) sử dụng mạng nơ-ron nhân tạo nhiều tầng."},{"id":58,"sentence":"The __________ is a famous behavioral evaluation proposed in 1950 to test whether a computer can exhibit human-equivalent intelligence.","answer":"Turing test","clue":"1950, human-equivalent intelligence","options":["Turing test","Stress test","Alpha test","Benchmark test"],"vn":"Phép thử Turing đánh giá trí tuệ máy móc có tương đương con người không."},{"id":59,"sentence":"In a __________ topology, all nodes are connected directly to a central networking device such as a switch or a hub.","answer":"star","clue":"connected directly to central networking device","options":["star","bus","ring","tree"],"vn":"Mạng hình sao (star topology) kết nối tất cả các máy vào thiết bị trung tâm."},{"id":60,"sentence":"While a hub broadcasts incoming packets to every connected port, a __________ inspects the destination hardware address and forwards data only to the designated port.","answer":"switch","clue":"forwards data only to designated port","options":["switch","repeater","terminator","cable connector"],"vn":"Switch đọc địa chỉ MAC đích để chuyển tiếp chính xác đến cổng nhận."},{"id":61,"sentence":"A __________ is a critical networking device that routes data packets between different IP networks and determines the most efficient path.","answer":"router","clue":"routes data packets between different IP networks","options":["router","monitor","projector","scanner"],"vn":"Bộ định tuyến (router) chuyển tiếp các gói tin giữa các mạng IP khác nhau."},{"id":62,"sentence":"In computer networks, __________ refers to the maximum volume of data that can be transmitted across a communication link in a specified period.","answer":"bandwidth","clue":"maximum volume of data","options":["bandwidth","latency","attenuation","resistance"],"vn":"Băng thông (bandwidth) là dung lượng dữ liệu tối đa truyền qua mạng."},{"id":63,"sentence":"The time delay experienced while a data packet travels from its source to its destination across a network is termed __________.","answer":"latency","clue":"time delay experienced while packet travels","options":["latency","bandwidth","capacity","frequency"],"vn":"Độ trễ (latency) là khoảng thời gian để gói tin đi từ nguồn đến đích."},{"id":64,"sentence":"Modern telecommunications rely heavily on __________ transmission, where information is encoded into binary digits rather than continuous waves.","answer":"digital","clue":"binary digits rather than continuous waves","options":["digital","analogue","manual","acoustic"],"vn":"Truyền dẫn số (digital) mã hóa dữ liệu thành các chữ số nhị phân 0-1."},{"id":65,"sentence":"One significant advantage of __________ is the elimination of daily commuting and greater flexibility, although workers may sometimes suffer from professional isolation.","answer":"teleworking","clue":"elimination of daily commuting","options":["teleworking","multiprocessing","overclocking","defragmenting"],"vn":"Làm việc từ xa (teleworking) tiết kiệm thời gian đi lại nhưng có thể gây cảm giác cô lập."},{"id":66,"sentence":"In web development, HTML dictates the content structure, while __________ is utilized to control the visual appearance, typography, and styling.","answer":"CSS","clue":"control visual appearance, styling","options":["CSS","SQL","BIOS","TCP"],"vn":"CSS định dạng kiểu dáng, giao diện và màu sắc cho tài liệu HTML."},{"id":67,"sentence":"To add dynamic and interactive behaviors to a website, such as validating form inputs or responding to button clicks, developers incorporate __________.","answer":"JavaScript","clue":"dynamic and interactive behaviors","options":["JavaScript","HTML","ASCII","XML"],"vn":"JavaScript giúp trang web có khả năng tương tác động và xử lý logic sự kiện."},{"id":68,"sentence":"A computer __________ is a standalone piece of malicious software that can replicate and spread across networks automatically without attaching to a host file.","answer":"worm","clue":"standalone, spread automatically without host file","options":["worm","macro virus","spreadsheet","cookie"],"vn":"Sâu máy tính (worm) tự nhân bản và lây lan qua mạng mà không cần bám vào file vật chủ."},{"id":69,"sentence":"A __________ attack attempts to disrupt normal network services by flooding the target server with an overwhelming volume of bogus traffic.","answer":"Denial of Service","clue":"flooding target server with bogus traffic","options":["Denial of Service","Phishing","Data encryption","Backup"],"vn":"Tấn công từ chối dịch vụ (Denial of Service - DoS) làm sập máy chủ bằng lượng truy cập rác khổng lồ."},{"id":70,"sentence":"In data cryptography, readable text before encryption is referred to as __________, whereas the scrambled unreadable output is ciphertext.","answer":"plaintext","clue":"readable text before encryption","options":["plaintext","ciphertext","password","algorithm"],"vn":"Văn bản gốc đọc được trước khi mã hóa gọi là bản rõ (plaintext)."},{"id":71,"sentence":"__________ encryption utilizes two distinct but mathematically related keys: a public key for encoding and a private key for decoding.","answer":"Asymmetric","clue":"public key for encoding and private key for decoding","options":["Asymmetric","Symmetric","Linear","Synchronous"],"vn":"Mã hóa bất đối xứng (Asymmetric) sử dụng cặp khóa công khai và khóa bí mật."},{"id":72,"sentence":"__________ security systems identify individuals by examining unique biological characteristics such as retinal scans, fingerprints, or voice prints.","answer":"Biometric","clue":"retinal scans, fingerprints, biological characteristics","options":["Biometric","Symmetric","Optical","Magnetic"],"vn":"Bảo mật sinh trắc học (Biometric) nhận dạng qua đặc điểm cơ thể con người."},{"id":73,"sentence":"The __________ describes a vast ecosystem of physical devices equipped with sensors and software that communicate and share information over the Internet.","answer":"Internet of Things","clue":"ecosystem of physical devices with sensors","options":["Internet of Things","Local Area Network","Token Ring","Dial-up network"],"vn":"Internet vạn vật (Internet of Things - IoT) kết nối các thiết bị thông minh qua cảm biến."},{"id":74,"sentence":"Unlike standard computers that process data using binary bits (0 or 1), quantum computers operate using __________, which can represent both states simultaneously.","answer":"qubits","clue":"quantum computers, both states simultaneously","options":["qubits","bytes","pixels","frames"],"vn":"Máy tính lượng tử sử dụng qubit có thể thể hiện đồng thời cả 0 và 1."},{"id":75,"sentence":"In cloud computing, __________ delivers ready-to-use software applications directly to users over a web browser, requiring no local installation or maintenance.","answer":"Software as a Service","clue":"delivers ready-to-use applications over web browser","options":["Software as a Service","Infrastructure as a Service","Platform as a Service","Hard disk partitioning"],"vn":"SaaS (Software as a Service) cung cấp phần mềm chạy trên web không cần cài đặt tại máy."},{"id":76,"sentence":"According to the reading, SSDs offer greater shock resistance and faster speeds because they have no moving __________ parts and use flash memory.","answer":"mechanical","clue":"no moving [?] parts","options":["mechanical","virtual","imaginary","digital"],"vn":"SSD không có bộ phận cơ học chuyển động (moving mechanical parts)."},{"id":77,"sentence":"Platform as a Service (PaaS) delivers a complete environment for developers to build, test, and __________ applications without managing underlying hardware.","answer":"deploy","clue":"build, test, and [?] applications","options":["deploy","destroy","erase","forbid"],"vn":"Triển khai ứng dụng (deploy applications)."},{"id":78,"sentence":"Webmail services like Gmail and web tools like Google Docs are prime examples of the __________ cloud service model.","answer":"SaaS","clue":"Gmail, Google Docs","options":["SaaS","IaaS","BIOS","LAN"],"vn":"Gmail và Google Docs là ví dụ điển hình của mô hình SaaS."},{"id":79,"sentence":"Human users often remain the weakest __________ in cybersecurity because cybercriminals manipulate them through phishing.","answer":"link","clue":"weakest [?] in cybersecurity","options":["link","chain","wall","gate"],"vn":"Mắt xích yếu nhất (weakest link) trong an ninh mạng."},{"id":80,"sentence":"To counteract credential theft, organizations must implement multi-factor __________ and conduct security training.","answer":"authentication","clue":"multi-factor [?]","options":["authentication","multiplication","distraction","destruction"],"vn":"Xác thực đa yếu tố (multi-factor authentication - MFA)."},{"id":81,"sentence":"Network administrators are responsible for __________ user accounts and access permissions.","answer":"configuring","clue":"user accounts and access permissions","options":["configuring","cooking","erasing randomly","drinking"],"vn":"Cấu hình tài khoản người dùng và phân quyền (configuring user accounts)."},{"id":82,"sentence":"Help desk technicians assist clients to __________ hardware and software problems.","answer":"troubleshoot","clue":"hardware and software problems","options":["troubleshoot","multiply","exaggerate","celebrate"],"vn":"Chẩn đoán và xử lý sự cố (troubleshoot problems)."},{"id":83,"sentence":"Database administrators must regularly __________ sensitive files to prevent data loss in case of hardware failure.","answer":"back up","clue":"files to prevent data loss","options":["back up","break down","throw out","sign out"],"vn":"Sao lưu dữ liệu dự phòng (back up files)."},{"id":84,"sentence":"In a relational database, programmers can __________ a query to extract specific records that meet certain criteria.","answer":"execute","clue":"a query to extract specific records","options":["execute","breathe","forget","paint"],"vn":"Thực thi câu truy vấn (execute a query)."},{"id":85,"sentence":"To protect data transmitted across public Wi-Fi networks, you should __________ sensitive information so unauthorized third parties cannot read it.","answer":"encrypt","clue":"sensitive information so third parties cannot read it","options":["encrypt","expose","delete","print"],"vn":"Mã hóa dữ liệu nhạy cảm (encrypt sensitive information)."},{"id":86,"sentence":"The operating system uses device drivers to __________ directly with peripheral hardware.","answer":"communicate","clue":"directly with peripheral hardware","options":["communicate","argue","isolate","disconnect"],"vn":"Giao tiếp/tương tác với phần cứng (communicate with hardware)."},{"id":87,"sentence":"Web developers apply Cascading Style Sheets (CSS) to __________ styles and layout to HTML documents.","answer":"apply","clue":"styles and layout to HTML","options":["apply","destroy","hide","refuse"],"vn":"Áp dụng định dạng phong cách (apply styles)."},{"id":88,"sentence":"During peak evening hours, network congestion can __________ data transmission speeds.","answer":"throttle","clue":"data transmission speeds","options":["throttle","invent","promote","celebrate"],"vn":"Bóp băng thông / giảm tốc độ đường truyền (throttle speeds)."},{"id":89,"sentence":"Organizations implement strict access control policies to prevent __________ users from accessing proprietary databases.","answer":"unauthorized","clue":"users from accessing databases","options":["unauthorized","registered","administrative","certified"],"vn":"Người dùng không được phép / truy cập trái phép (unauthorized users)."},{"id":90,"sentence":"A fiber-optic cable transmits information as pulses of __________ through flexible strands of glass.","answer":"light","clue":"pulses of [?] through strands of glass","options":["light","sound","water","metal"],"vn":"Cáp quang truyền thông tin dưới dạng các xung ánh sáng (pulses of light)."}],"part3Data":[{"id":1,"text":"A cloud database is an automated or built-in database for such a virtualized environment.","answer":true,"reason":"ĐÚNG: Khái niệm chuẩn của Cloud database hoạt động trong môi trường ảo hóa.","clue":"Cloud database ... virtualized environment","tip":"Định nghĩa chuẩn xác: Cloud database vận hành trên nền tảng ảo hóa đám mây."},{"id":2,"text":"A cloud database is used for large data sets.","answer":true,"reason":"ĐÚNG: Cloud database thiết kế tối ưu cho tập dữ liệu lớn (Big data / large data sets).","clue":"Cloud database ... large data sets","tip":"Cloud database được tối ưu đặc biệt cho các tập dữ liệu lớn."},{"id":3,"text":"A cloud service offers various advantages... as well as low availability.","answer":false,"reason":"SAI: Dịch vụ đám mây đem lại ĐỘ SẴN SÀNG CAO (high availability), không phải 'low'.","clue":"low availability","tip":"Bẫy từ 'low'! Dịch vụ đám mây (Cloud) nổi tiếng vì độ sẵn sàng cao (HIGH availability), không bao giờ là 'low'."},{"id":4,"text":"A database query function allows you to extract information according to certain conditions or criteria.","answer":true,"reason":"ĐÚNG: Hàm truy vấn (query) dùng để trích xuất dữ liệu theo điều kiện/tiêu chí.","clue":"query function ... extract information","tip":"Chức năng truy vấn (query) cho phép trích xuất thông tin theo tiêu chí nhất định."},{"id":5,"text":"A database query function allows you to extract information according to certain conditions or criteria.","answer":true,"reason":"ĐÚNG: Câu lặp lại của câu 4.","clue":"query function ... extract information","tip":"Chức năng truy vấn (query) cho phép trích xuất thông tin theo tiêu chí nhất định."},{"id":6,"text":"A field is a group of records holding large amount of information.","answer":false,"reason":"SAI: Bẫy tráo khái niệm! 'Record' mới là nhóm các fields, còn field là trường đơn lẻ (như Name, Age).","clue":"field is a group of records","tip":"Bẫy tráo khái niệm! 'Record' mới là nhóm các fields, còn field chỉ là 1 cột thuộc tính đơn lẻ."},{"id":7,"text":"A LAN connects computers in an office building, school, over a relatively long distance.","answer":false,"reason":"SAI: Bẫy từ 'long distance'! LAN là mạng cục bộ khoảng cách NGẮN (short distance), WAN mới là long distance.","clue":"LAN ... long distance","tip":"Bẫy từ 'long distance'! LAN là mạng cục bộ khoảng cách NGẮN (short distance), WAN mới là long."},{"id":8,"text":"A mainframe computer is less powerful than a PC.","answer":false,"reason":"SAI: Bẫy từ 'less powerful'! Máy tính lớn (Mainframe) MẠNH HƠN RẤT NHIỀU (more powerful) so với PC cá nhân.","clue":"less powerful","tip":"Bẫy từ 'less powerful'! Mainframe (máy tính lớn) mạnh hơn rất nhiều (MORE powerful) so với PC cá nhân."},{"id":9,"text":"A mainframe computer is more powerful than a PC.","answer":true,"reason":"ĐÚNG: Mainframe mạnh hơn PC.","clue":"more powerful","tip":"Mainframe máy tính khổng lồ chắc chắn mạnh hơn PC cá nhân."},{"id":10,"text":"A mainframe is used by large organizations that need to process great amount of data.","answer":true,"reason":"ĐÚNG: Mainframe dùng cho các tập đoàn lớn xử lý lượng dữ liệu khổng lồ.","clue":"great amount of data","tip":"Mainframe được các tập đoàn lớn dùng để xử lý lượng dữ liệu cực lớn."},{"id":11,"text":"A mainframe is used by large organizations that need to process small amount of data.","answer":false,"reason":"SAI: Bẫy từ 'small amount'! Xử lý lượng dữ liệu lớn (great amount), không phải nhỏ.","clue":"small amount of data","tip":"Bẫy từ 'small'! Mainframe xử lý lượng dữ liệu khổng lồ (GREAT amount), không phải dữ liệu nhỏ."},{"id":12,"text":"A MAN is a specialized network that provides access to block-level storage...","answer":false,"reason":"SAI: Đây là định nghĩa của SAN (Storage Area Network), không phải MAN (Metropolitan Area Network).","clue":"MAN ... block-level storage","tip":"Bẫy tráo tên mạng! Cung cấp lưu trữ block-level là mạng SAN (Storage Area Network), MAN là mạng đô thị."},{"id":13,"text":"A Personal Database is an automated or built-in database for such a virtualized environment.","answer":false,"reason":"SAI: Đây là định nghĩa của Cloud database, không phải Personal Database!","clue":"Personal Database ... virtualized environment","tip":"Bẫy tráo khái niệm! Môi trường ảo hóa (virtualized) là Cloud Database, Personal DB là cho cá nhân."},{"id":14,"text":"A Personal Digital Assistant is small enough to fit into the palm of your hand.","answer":true,"reason":"ĐÚNG: Thiết bị trợ lý số cá nhân PDA nhỏ gọn vừa lòng bàn tay.","clue":"palm of your hand","tip":"PDA (Personal Digital Assistant) là thiết bị trợ lý số bỏ túi nhỏ gọn vừa lòng bàn tay."},{"id":15,"text":"A VPN establishes an encrypted channel that keeps a user’s identity and access credentials... inaccessible to hackers.","answer":true,"reason":"ĐÚNG: VPN mã hóa đường truyền ngăn chặn hacker nghe lén.","clue":"VPN ... encrypted channel","tip":"VPN luôn gắn liền với kênh truyền được mã hóa (encrypted channel) bảo mật."},{"id":16,"text":"A Web Application Firewall (WAF) which updates a threat database in real-time is one of the effective ways to filter application input to protect against code injection.","answer":true,"reason":"ĐÚNG: WAF bảo vệ chống tấn công SQL/Code Injection thời gian thực.","clue":"WAF ... protect against code injection","tip":"Tường lửa ứng dụng web (WAF) cập nhật thời gian thực để ngăn chặn tấn công chèn mã độc (code injection)."},{"id":17,"text":"A wireless access point allows wireless devices to connect to the network.","answer":true,"reason":"ĐÚNG: Điểm truy cập Access Point cho phép thiết bị không dây kết nối mạng.","clue":"wireless access point ... connect","tip":"Access Point (AP) chính là điểm phát cho các thiết bị không dây kết nối vào mạng."},{"id":18,"text":"Animations are placed around pieces of text to tell the web browser how to display text or pictures.","answer":false,"reason":"SAI: Đây là định nghĩa của Thẻ HTML (Tags), animations là ảnh động!","clue":"Animations ... placed around pieces of text","tip":"Bẫy tráo khái niệm! Đặt bao quanh đoạn văn bản trên web là Thẻ Tags HTML, Animations là hoạt ảnh/hình động."},{"id":19,"text":"Background means the underlying colors and patterns of a web page.","answer":true,"reason":"ĐÚNG: Background là màu nền và họa tiết web.","clue":"Background ... colors and patterns","tip":"Background chính là màu nền và họa tiết cơ sở của trang web."},{"id":20,"text":"Centralized Database are the paid versions of the enormous databases, designed for users who wish to access the information for assistance.","answer":false,"reason":"SAI: CSDL tập trung là lưu trữ dữ liệu tại một nơi trung tâm, không phải bản trả phí.","clue":"Centralized Database ... paid versions","tip":"Bẫy khái niệm! Bản thương mại trả phí là Commercial Database, Centralized DB chỉ là lưu trữ tập trung."},{"id":21,"text":"Digital TV is a way of transmitting pictures by means of digital signals, in contrast to the analogue signals used by traditional TV.","answer":true,"reason":"ĐÚNG: Truyền hình số truyền tín hiệu số (digital) thay vì analog truyền thống.","clue":"Digital TV ... digital signals","tip":"Truyền hình số (Digital TV) truyền tín hiệu kỹ thuật số, đối lập với analog cổ điển."},{"id":22,"text":"E-mail, telephone, video calling, FAX machine are typically used to transmit information in electronic communication.","answer":true,"reason":"ĐÚNG: Các phương tiện truyền thông điện tử phổ biến.","clue":"E-mail, telephone, video calling, FAX","tip":"Tất cả các phương tiện này đều thuộc truyền thông điện tử (electronic communication)."},{"id":23,"text":"Hackers are always looking to exploit a private network or system's vulnerabilities so they can steal confidential information and data.","answer":true,"reason":"ĐÚNG: Tin tặc luôn tìm cách khai thác lỗ hổng để đánh cắp dữ liệu.","clue":"Hackers ... steal confidential/secret information","tip":"Tin tặc luôn nhắm vào các lỗ hổng (vulnerabilities) để đánh cắp thông tin bí mật."},{"id":24,"text":"Hackers are always trying to attack a private network or system's vulnerabilities so they can steal secret information and data.","answer":true,"reason":"ĐÚNG: Tương tự câu 23.","clue":"Hackers ... steal confidential/secret information","tip":"Tin tặc luôn nhắm vào các lỗ hổng (vulnerabilities) để đánh cắp thông tin bí mật."},{"id":25,"text":"Hackers are always trying to attack a private network or system’s vulnerabilities so they can steal secret information and data.","answer":true,"reason":"ĐÚNG: Tương tự câu 23 & 24.","clue":"Hackers ... steal confidential/secret information","tip":"Tin tặc luôn nhắm vào các lỗ hổng (vulnerabilities) để đánh cắp thông tin bí mật."},{"id":26,"text":"Hardware is any physical part of the computer which includes the internal components and the external parts like the monitor and printer.","answer":true,"reason":"ĐÚNG: Phần cứng bao gồm cả linh kiện bên trong và thiết bị bên ngoài.","clue":"Hardware ... physical part","tip":"Phần cứng (Hardware) bao gồm tất cả các linh kiện vật lý (physical) bên trong và bên ngoài máy tính."},{"id":27,"text":"If you want to protect your PC, don’t open email attachments from strangers and take care when downloading files from the Web.","answer":true,"reason":"ĐÚNG: Lời khuyên bảo mật cơ bản: không mở file đính kèm lạ.","clue":"don't open email attachments from strangers","tip":"Nguyên tắc an toàn cơ bản: không mở file đính kèm từ người lạ để tránh mã độc."},{"id":28,"text":"If you want to send instant messages on Facebook Messenger, Whatsapp or Snapchat, you will be charged a large amount of fee.","answer":false,"reason":"SAI: Bẫy 'large amount of fee'! Các ứng dụng này gửi tin nhắn MIỄN PHÍ (free) qua Internet.","clue":"large amount of fee","tip":"Bẫy từ 'large amount of fee'! Nhắn tin Messenger, WhatsApp, Snapchat hoàn toàn MIỄN PHÍ qua Internet."},{"id":29,"text":"If your computer is attacked by ransomware, you don’t have to pay any ransom to unlock your screen and your files.","answer":false,"reason":"SAI: Ransomware tống tiền bắt nạn nhân PHẢI trả tiền chuộc mới mở khóa file.","clue":"don't have to pay any ransom","tip":"Bẫy từ 'don't have to pay'! Ransomware tống tiền bắt buộc nạn nhân PHẢI trả tiền chuộc mới mong mở file."},{"id":30,"text":"In a star bus network, each node is connected to its left in a circle.","answer":false,"reason":"SAI: Kết nối thành vòng tròn là RING network, không phải star bus!","clue":"star bus ... connected in a circle","tip":"Bẫy tráo mô hình! Nối thành vòng tròn (in a circle) là mạng VÒNG (Ring network), không phải star bus."},{"id":31,"text":"In distribution database, the data is stored centrally and user from various locations can access this data.","answer":false,"reason":"SAI: CSDL phân tán thì dữ liệu lưu ở nhiều nơi, lưu tập trung là CENTRALIZED database!","clue":"distribution database ... stored centrally","tip":"Bẫy tráo khái niệm! Đã là CSDL phân tán (distribution) thì dữ liệu chia nhiều nơi, lưu tập trung là Centralized."},{"id":32,"text":"Instant message is a kind of service that allows people to send short message for free.","answer":true,"reason":"ĐÚNG: Nhắn tin tức thời là dịch vụ nhắn tin ngắn miễn phí.","clue":"Instant message ... short message for free","tip":"Nhắn tin tức thời (Instant message) gửi tin nhắn ngắn miễn phí qua mạng."},{"id":33,"text":"Instant messages are sent for free over the internet and can contain multimedia items like emoji, pictures, videos and voice recordings.","answer":true,"reason":"ĐÚNG: Tin nhắn tức thời gửi miễn phí và hỗ trợ đa phương tiện.","clue":"Instant messages ... emoji, pictures, videos","tip":"Tin nhắn tức thời ngày nay đều hỗ trợ chèn đa phương tiện (emoji, ảnh, video, âm thanh)."},{"id":34,"text":"Instant messages are sent for free over the internet and can contain multimedia items like emoji, pictures, videos and voice recordings.","answer":true,"reason":"ĐÚNG: Câu lặp lại câu 33.","clue":"Instant messages ... emoji, pictures, videos","tip":"Tin nhắn tức thời ngày nay đều hỗ trợ chèn đa phương tiện (emoji, ảnh, video, âm thanh)."},{"id":35,"text":"Malware attack is malicious software that changes a browser's behavior, settings, or appearance without user consent.","answer":false,"reason":"SAI: Đây là định nghĩa chính xác của BROWSER HIJACKER, không phải chung chung là malware attack.","clue":"changes a browser's behavior","tip":"Bẫy khái niệm chung chung! Thay đổi hành vi và giao diện trình duyệt là BROWSER HIJACKER."},{"id":36,"text":"MANs are typically bigger than LANs but smaller and WANs.","answer":true,"reason":"ĐÚNG: Mạng đô thị MAN lớn hơn LAN nhưng nhỏ hơn WAN (LAN < MAN < WAN).","clue":"MANs bigger than LANs but smaller and WANs","tip":"Quy mô chuẩn: Mạng cục bộ LAN < Mạng đô thị MAN < Mạng diện rộng WAN."},{"id":37,"text":"Meta tag is invisible information (e.g. a hidden keyword) on a website.","answer":true,"reason":"ĐÚNG: Meta tag chứa thông tin vô hình/ẩn phục vụ tìm kiếm SEO.","clue":"Meta tag ... invisible information","tip":"Thẻ meta tag chứa thông tin vô hình đối với người đọc nhưng quan trọng cho công cụ tìm kiếm."},{"id":38,"text":"Neural networks are used to convert handwritten characters into digital characters that a machine can recognize.","answer":true,"reason":"ĐÚNG: Mạng nơ-ron được ứng dụng nhận diện chữ viết tay số hóa (OCR).","clue":"Neural networks ... handwritten into digital characters","tip":"Mạng nơ-ron được dùng trong nhận dạng chữ viết tay thành văn bản số (OCR)."},{"id":39,"text":"Peripherals are the physical units attached to the computer. They include storage devices and input/output devices.","answer":true,"reason":"ĐÚNG: Thiết bị ngoại vi gắn ngoài gồm thiết bị lưu trữ và vào/ra.","clue":"Peripherals ... attached to the computer","tip":"Thiết bị ngoại vi là các linh kiện vật lý được gắn thêm vào máy tính (bàn phím, chuột, máy in...)."},{"id":40,"text":"Phishing is a cyber-attack in which phishing emails are sent to gather users’ login information.","answer":true,"reason":"ĐÚNG: Phishing (lừa đảo) gửi email giả mạo để lấy trộm mật khẩu/thông tin đăng nhập.","clue":"Phishing ... emails to gather login information","tip":"Phishing là tấn công giả mạo email để lừa lấy cắp thông tin đăng nhập/mật khẩu."},{"id":41,"text":"Private networks can’t be attacked by intruders who attempt to obtain information such as Social Security numbers, bank accounts...","answer":false,"reason":"SAI: Bẫy từ 'can't be attacked'! Mạng riêng tư VẪN CÓ THỂ bị kẻ xấu tấn công nếu có lỗ hổng.","clue":"can't be attacked","tip":"Bẫy từ tuyệt đối 'can't be attacked'! Mạng riêng tư VẪN CÓ THỂ bị tin tặc tấn công nếu có lỗ hổng."},{"id":42,"text":"Relational database is the database which is made up of related files.","answer":true,"reason":"ĐÚNG: CSDL quan hệ được cấu thành từ các bảng/tệp có mối liên hệ.","clue":"Relational database ... related files","tip":"Cơ sở dữ liệu quan hệ (Relational DB) gồm các bảng/tệp liên kết chặt chẽ với nhau."},{"id":43,"text":"Systems Administrators, Network Administrators, or anyone who has anything to do with cybersecurity will also be under a great deal of stress.","answer":true,"reason":"ĐÚNG: Dân IT quản trị hệ thống và an ninh mạng chịu áp lực công việc rất lớn.","clue":"Systems Administrators ... great deal of stress","tip":"Quản trị viên hệ thống và an ninh mạng chịu áp lực và căng thẳng công việc rất cao."},{"id":44,"text":"Tech professionals are not required to constantly keep themselves up-to-date on the latest trends and developments.","answer":false,"reason":"SAI: Bẫy từ 'not required'! Dân công nghệ BẮT BUỘC phải liên tục cập nhật kiến thức mới.","clue":"not required to keep up-to-date","tip":"Bẫy từ 'not required'! Dân công nghệ BẮT BUỘC (required) phải liên tục học và cập nhật cái mới."},{"id":45,"text":"Thanks to electronic communication, mobile phones now let you check your email, browse the Web and connect with home or company intranets, all without wire.","answer":true,"reason":"ĐÚNG: Điện thoại di động cho phép lướt web, check mail hoàn toàn không dây.","clue":"mobile phones ... without wire","tip":"Điện thoại di động giúp kết nối mạng, đọc email hoàn toàn không dây (without wire)."},{"id":46,"text":"The analysis of large-size, unstructured information can’t be done very efficiently on several cloud virtual servers.","answer":false,"reason":"SAI: Bẫy từ 'can't'! Phân tích dữ liệu lớn CÓ THỂ thực hiện rất hiệu quả trên các máy chủ ảo đám mây.","clue":"can't be done very efficiently","tip":"Bẫy từ 'can't'! Phân tích dữ liệu lớn CÓ THỂ thực hiện rất hiệu quả trên các máy chủ ảo đám mây."},{"id":47,"text":"The connection between devices of WLAN and LAN are the same.","answer":false,"reason":"SAI: Khác nhau! WLAN dùng sóng vô tuyến không dây (wireless), LAN dùng dây cáp mạng (cables).","clue":"WLAN and LAN are the same","tip":"Bẫy từ 'the same'! Khác nhau hoàn toàn: WLAN dùng sóng vô tuyến (wireless), LAN dùng dây cáp."},{"id":48,"text":"The network starts with an input layer that receives output in the form of data.","answer":false,"reason":"SAI: Tầng đầu vào (input layer) thì nhận 'INPUT' (dữ liệu vào), không phải nhận 'output'!","clue":"input layer that receives output","tip":"Bẫy tráo từ đối lập! Tầng đầu vào (INPUT layer) thì phải nhận 'input', không thể nhận 'output'."},{"id":49,"text":"Vlogging and Blogging are similar in delivering informal styles, however, with Vlogging, Vloggers can post videos.","answer":true,"reason":"ĐÚNG: Vlogging và Blogging tương đồng, điểm khác biệt là Vlogging dùng video.","clue":"Vlogging ... post videos","tip":"Vlogging (Video Blogging) khác biệt ở chỗ chia sẻ nội dung qua định dạng video."},{"id":50,"text":"VOIP allows voice and multimedia data to be transferred across a data network.","answer":true,"reason":"ĐÚNG: VOIP cho phép truyền âm thanh giọng nói và đa phương tiện qua mạng dữ liệu.","clue":"VOIP ... voice and multimedia","tip":"VOIP truyền tải âm thanh giọng nói và dữ liệu đa phương tiện qua hạ tầng mạng IP."},{"id":51,"text":"A software developer is primarily responsible for inspecting and fixing physical cable connections and computer power sockets.","answer":false,"reason":"SAI: Đây là công việc của kỹ thuật viên phần cứng (support technician); software developer phụ trách viết mã nguồn và giải thuật.","clue":"developer ... fixing physical cable connections","tip":"Bẫy tráo chức danh nghề nghiệp! Developer phụ trách viết mã và phần mềm, không phải sửa dây cáp phần cứng."},{"id":52,"text":"The Arithmetic Logic Unit (ALU) decides which instructions to fetch from RAM and directs the overall timing and coordination of hardware components.","answer":false,"reason":"SAI: Khối điều khiển (Control Unit - CU) mới điều phối và nạp lệnh; ALU chỉ thực hiện các phép tính số học và so sánh logic.","clue":"ALU ... directs overall timing and coordination","tip":"Bẫy tráo khối chức năng trong CPU! Điều phối nạp lệnh là CU, tính toán số học logic là ALU."},{"id":53,"text":"Solid State Drives (SSDs) are more durable and provide faster read/write speeds than traditional HDDs because they contain no moving mechanical parts.","answer":true,"reason":"ĐÚNG: SSD dùng chip flash bán dẫn, không có đĩa quay cơ học nên tốc độ vượt trội và chống sốc tốt.","clue":"SSDs ... no moving mechanical parts","tip":"SSD tốc độ cao và bền hơn HDD nhờ dùng chip nhớ flash không chuyển động cơ học."},{"id":54,"text":"Data redundancy in a database can lead to data inconsistency and unnecessary consumption of storage capacity.","answer":true,"reason":"ĐÚNG: Dư thừa dữ liệu làm tốn dung lượng lưu trữ và dẫn tới việc dữ liệu cập nhật không đồng nhất.","clue":"Data redundancy ... inconsistency","tip":"Dư thừa dữ liệu (Data redundancy) gây lãng phí bộ nhớ và dẫn đến dữ liệu không nhất quán."},{"id":55,"text":"A foreign key in a relational database table must always contain unique values and cannot have duplicate entries.","answer":false,"reason":"SAI: Chỉ có Primary Key (Khóa chính) mới bắt buộc phải unique; Foreign Key (Khóa ngoại) được phép lặp lại để thể hiện quan hệ 1-Nhiều.","clue":"foreign key ... must always contain unique values","tip":"Bẫy tráo Khóa chính & Khóa ngoại! Khóa chính mới bắt buộc unique, khóa ngoại được phép trùng giá trị."},{"id":56,"text":"The SQL DELETE command is used to remove a table schema completely from the database structure.","answer":false,"reason":"SAI: Lệnh DELETE chỉ xóa các dòng dữ liệu trong bảng; muốn xóa cấu trúc toàn bộ bảng phải dùng lệnh DROP TABLE.","clue":"DELETE ... remove table schema completely","tip":"Bẫy lệnh SQL! DELETE chỉ xóa dòng bản ghi, DROP TABLE mới xóa toàn bộ bảng và cấu trúc."},{"id":57,"text":"Narrow AI (Weak AI) refers to systems that possess general human cognitive intelligence and can adapt to solve any domain-independent task.","answer":false,"reason":"SAI: Hệ thống có trí thông minh tổng quát giải mọi bài toán là General AI (Strong AI); Narrow AI chỉ giải quyết một bài toán cụ thể.","clue":"Narrow AI ... solve any domain-independent task","tip":"Bẫy đối lập Narrow AI vs General AI! Trí tuệ tổng quát như con người là General AI, Narrow AI chỉ làm 1 việc hẹp."},{"id":58,"text":"Deep learning models use artificial neural networks consisting of an input layer, one or more hidden layers, and an output layer.","answer":true,"reason":"ĐÚNG: Mô hình Deep learning dùng mạng nơ-ron nhân tạo với các lớp ẩn (hidden layers) phân tích dữ liệu phức tạp.","clue":"Deep learning ... hidden layers","tip":"Deep learning có cấu trúc gồm lớp đầu vào, một hoặc nhiều lớp ẩn và lớp đầu ra."},{"id":59,"text":"In a star network topology, if the central hub or switch fails, only that single central port is affected while other connected computers communicate normally.","answer":false,"reason":"SAI: Trong mạng hình sao, thiết bị trung tâm bị hỏng sẽ làm TOÀN BỘ mạng bị sập; chỉ khi đứt dây máy con thì các máy khác mới hoạt động được.","clue":"star topology ... central hub fails ... other computers normal","tip":"Bẫy mạng hình sao! Thiết bị trung tâm (hub/switch) sập thì toàn bộ mạng bị tê liệt ngay lập tức."},{"id":60,"text":"A network switch is smarter than a hub because it reads destination MAC addresses and sends frames specifically to the intended recipient device.","answer":true,"reason":"ĐÚNG: Switch lưu bảng địa chỉ MAC và chuyển dữ liệu trực tiếp đến máy nhận, không phát tán (broadcast) bừa bãi như hub.","clue":"switch ... destination MAC addresses ... intended recipient","tip":"Switch thông minh hơn hub vì dùng địa chỉ MAC chuyển gói tin chính xác đến cổng đích."},{"id":61,"text":"Routers operate at the network layer to forward data packets between different IP networks based on logical IP addresses.","answer":true,"reason":"ĐÚNG: Router định tuyến các gói tin giữa các mạng IP khác nhau dựa trên địa chỉ IP logic.","clue":"Routers ... different IP networks ... logical IP addresses","tip":"Router làm việc ở tầng mạng định tuyến gói tin giữa các mạng IP khác nhau."},{"id":62,"text":"Bandwidth and latency are synonymous terms that both refer to the delay of data transmission in a network.","answer":false,"reason":"SAI: Bandwidth (băng thông) là độ rộng/dung lượng truyền tải (Mbps/Gbps); Latency (độ trễ) là thời gian trễ của gói tin (ms).","clue":"Bandwidth and latency are synonymous terms","tip":"Bẫy từ 'synonymous' (đồng nghĩa)! Băng thông (dung lượng) và Độ trễ (thời gian delay) là 2 khái niệm khác biệt."},{"id":63,"text":"Fiber-optic cables carry data as pulses of light through thin strands of glass, offering much higher bandwidth and immunity to electromagnetic interference compared to copper cables.","answer":true,"reason":"ĐÚNG: Cáp quang truyền dữ liệu bằng xung ánh sáng qua sợi thủy tinh, tốc độ cao và miễn nhiễm nhiễu điện từ.","clue":"Fiber-optic ... pulses of light ... strands of glass","tip":"Cáp sợi quang truyền bằng ánh sáng qua sợi thủy tinh, không bị nhiễu điện từ và băng thông rất cao."},{"id":64,"text":"Teleworking provides workers with flexible schedules and saves travel time, but it may lead to feelings of isolation and blurred boundaries between work and personal life.","answer":true,"reason":"ĐÚNG: Nhận định chuẩn xác về ưu điểm (linh hoạt, tiết kiệm đi lại) và nhược điểm (cô lập, xáo trộn công việc - đời sống) của làm việc từ xa.","clue":"Teleworking ... flexible schedules ... feelings of isolation","tip":"Làm việc từ xa (Teleworking) linh hoạt giờ giấc nhưng có thể gây cảm giác cô lập xã hội."},{"id":65,"text":"HTML files are responsible for storing user database records, while SQL is used exclusively to display web layouts inside browser windows.","answer":false,"reason":"SAI: Bẫy tráo vai trò công nghệ! HTML dùng hiển thị layout trên web, SQL dùng truy vấn cơ sở dữ liệu.","clue":"HTML ... storing database records ... SQL ... display web layouts","tip":"Bẫy tráo công nghệ! HTML để bố cục trang web, SQL để quản lý bản ghi cơ sở dữ liệu."},{"id":66,"text":"A computer virus can spread independently across an entire network without needing any user interaction or host program to execute it.","answer":false,"reason":"SAI: Sâu máy tính (Worm) mới tự lây lan độc lập qua mạng; Virus BẮT BUỘC phải bám vào file vật chủ (host program) và cần kích hoạt mở file.","clue":"virus ... spread independently without user interaction or host program","tip":"Bẫy kinh điển: Virus vs Worm! Worm tự lây lan độc lập, Virus phải bám vào file vật chủ."},{"id":67,"text":"In asymmetric encryption, the public key is shared freely with everyone to encrypt messages, but only the corresponding private key can decrypt them.","answer":true,"reason":"ĐÚNG: Nguyên lý mật mã khóa công khai: khóa công khai dùng để mã hóa, khóa bí mật dùng để giải mã.","clue":"asymmetric encryption ... public key encrypt ... private key decrypt","tip":"Mã hóa bất đối xứng: Ai cũng có thể dùng khóa công khai để mã hóa, chỉ chủ sở hữu có khóa bí mật mới giải mã được."},{"id":68,"text":"A Denial of Service (DoS) attack is designed to secretly alter web browser settings and install unwanted advertising toolbars on a user's computer.","answer":false,"reason":"SAI: Đổi cài đặt trình duyệt và chèn quảng cáo là Browser Hijacker/Adware; DoS là tấn công làm nghẽn/sập máy chủ bằng lưu lượng rác khổng lồ.","clue":"DoS ... alter web browser settings and install advertising toolbars","tip":"Bẫy khái niệm an ninh mạng! Chèn quảng cáo là Adware/Hijacker, DoS là làm nghẽn sập máy chủ."},{"id":69,"text":"Multi-Factor Authentication (MFA) enhances account security by requiring two or more independent credentials before granting access.","answer":true,"reason":"ĐÚNG: MFA tăng cường bảo mật bằng cách đòi hỏi từ 2 yếu tố xác thực độc lập trở lên (mật khẩu + OTP/vân tay).","clue":"Multi-Factor Authentication ... two or more independent credentials","tip":"Xác thực đa yếu tố (MFA) kết hợp mật khẩu với mã xác nhận hoặc sinh trắc học để tăng cường an toàn."},{"id":70,"text":"Quantum computing relies on traditional binary bits that can only exist strictly in a single deterministic state of either 0 or 1.","answer":false,"reason":"SAI: Máy tính lượng tử dùng qubit dựa trên nguyên lý chồng chập (superposition) thể hiện đồng thời cả 0 và 1, máy tính truyền thống mới dùng bit nhị phân cố định.","clue":"Quantum computing ... strictly in a single state of either 0 or 1","tip":"Bẫy đối lập Lượng tử vs Truyền thống! Bit nhị phân chỉ là 0 hoặc 1, Qubit lượng tử tồn tại đồng thời cả 0 và 1."}]};
